using System.IO;using System.Reflection;using System.Text.Json;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using RAWSelectionAssistant.Core.Services.Projects;using RAWSelectionAssistant.ViewModels;using RAWSelectionAssistant.Views;using RAWSelectionAssistant.Services;using static RAWSelectionAssistant.WpfTests.RuntimeCorrectionWpfTests;
namespace RAWSelectionAssistant.WpfTests;
[TestClass][DoNotParallelize]public sealed class R54StageLayoutTests
{
 static IEnumerable<T> Walk<T>(DependencyObject d)where T:DependencyObject{if(d is T t)yield return t;for(int i=0;i<VisualTreeHelper.GetChildrenCount(d);i++)foreach(var x in Walk<T>(VisualTreeHelper.GetChild(d,i)))yield return x;}
 static void Layout(FrameworkElement v,int w,int h){v.Measure(new Size(w,h));v.Arrange(new Rect(0,0,w,h));v.UpdateLayout();}
 static void Invoke(PhotoGradePageView v,string method){var m=typeof(PhotoGradePageView).GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic)!;m.Invoke(v,m.GetParameters().Length==0?null:[v,new RoutedEventArgs()]);}
 static string Image(string root){Directory.CreateDirectory(root);var a=new byte[160*100*3];for(int i=0;i<a.Length;i++)a[i]=(byte)(i%251);var b=BitmapSource.Create(160,100,96,96,PixelFormats.Rgb24,null,a,480);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(b));var path=Path.Combine(root,"input.png");using var f=File.Create(path);png.Save(f);return path;}
 static void Capture(FrameworkElement v,string path){var png=new PngBitmapEncoder();var b=new RenderTargetBitmap((int)v.ActualWidth,(int)v.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(v);png.Frames.Add(BitmapFrame.Create(b));using var f=File.Create(path);png.Save(f);}
 [TestMethod]public Task WheelsAndScopesUseSelectedNodeAndRememberPresentation()=>RunSta(async()=>
 {
  var root=Environment.GetEnvironmentVariable("KITAO_STAGE_UI")??throw new InvalidOperationException("explicit output required");EnsureTestApplication();using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs());await vm.LoadTargetAsync(Image(root));await vm.CreateR53VariantAsync(true);var e=vm.Editor;e.AddAdjustmentNodeCommand.Execute("ColorBalance");var first=e.SelectedAdjustmentNode!.Id;e.AddAdjustmentNodeCommand.Execute("ColorBalance");var second=e.SelectedAdjustmentNode!.Id;
  var page=new PhotoGradePageView{DataContext=vm};Layout(page,1366,768);vm.R53Professional=true;Invoke(page,"OpenR53Panel");page.SelectClosureNodeTool("色轮");page.ApplyR53Layout();Layout(page,1366,768);
  var area=(ScrollViewer)page.FindName("AdjustmentScroll");var wheels=Walk<StudioColorBalanceWheel>(area).ToArray();Assert.AreEqual(4,wheels.Length);foreach(var wheel in wheels){Assert.IsTrue(wheel.ActualWidth>=100);Assert.IsTrue(wheel.ActualHeight>=100);}
  var hue=ColorStudioToolCatalog.GetParameters(ColorStudioNodeType.ColorBalance).Single(p=>p.Key=="shadows_hue");var amount=ColorStudioToolCatalog.GetParameters(ColorStudioNodeType.ColorBalance).Single(p=>p.Key=="shadows_amount");
  var shadows=wheels[0];var update=typeof(StudioColorBalanceWheel).GetMethod("Update",BindingFlags.Instance|BindingFlags.NonPublic)!;e.BeginEditTransaction();update.Invoke(shadows,[new Point(shadows.ActualWidth*.75,shadows.ActualHeight*.5)]);e.CommitEditTransaction();Assert.IsTrue(e.ToolValue(amount)>0);Assert.AreEqual(second,e.SelectedAdjustmentNode!.Id);Assert.AreEqual(0,ColorStudioToolCatalog.Value(e.AdjustmentNodes.Single(n=>n.Id==first),"shadows_amount"));e.UndoAdjustmentCommand.Execute(null);Assert.AreEqual(0,e.ToolValue(amount));
  var numeric=Walk<StudioNumericEditor>(area).First(x=>System.Windows.Automation.AutomationProperties.GetName(x)=="暗部色相");numeric.Text="120";Assert.IsTrue(numeric.CommitDraft());Assert.AreEqual(120,e.ToolValue(hue));var reset=Walk<Button>(area).First(x=>System.Windows.Automation.AutomationProperties.GetName(x)=="复位暗部色轮");reset.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Assert.AreEqual(0,e.ToolValue(hue));Capture(page,Path.Combine(root,"wheels-1366-OFFSCREEN.png"));
  Assert.AreEqual(22d,((ColumnDefinition)page.FindName("R54ScopesColumn")).Width.Value);Invoke(page,"R53ToggleScopes");Layout(page,1366,768);Assert.AreEqual(232d,((ColumnDefinition)page.FindName("R54ScopesColumn")).Width.Value);Assert.AreEqual(Visibility.Visible,((Border)page.FindName("R54ScopesPanel")).Visibility);Assert.AreEqual(3,Grid.GetRow((Border)page.FindName("FilmstripArea")));var scope=Walk<StudioScopeView>((Border)page.FindName("R54ScopesPanel")).First(x=>x.Mode=="波形");await scope.AnalysisWork;page.UpdateLayout();Capture(page,Path.Combine(root,"scopes-1366-OFFSCREEN.png"));
  vm.R53Professional=false;page.ApplyR53Layout();Assert.AreEqual(0d,((ColumnDefinition)page.FindName("R54ScopesColumn")).Width.Value);vm.R53Professional=true;page.ApplyR53Layout();Assert.AreEqual(232d,((ColumnDefinition)page.FindName("R54ScopesColumn")).Width.Value);Layout(page,1920,1080);Assert.AreEqual(true,vm.Layout.R54ScopesOpen);Layout(page,900,600);Assert.IsTrue(((ColumnDefinition)page.FindName("R54ScopesColumn")).Width.Value>=120);Invoke(page,"R53ToggleScopes");Assert.AreEqual(22d,((ColumnDefinition)page.FindName("R54ScopesColumn")).Width.Value);
  var saved=JsonSerializer.Serialize(vm.Layout);Assert.AreEqual(false,JsonSerializer.Deserialize<ColorStudioLayout>(saved)!.Normalize().R54ScopesOpen);page.DataContext=null;
 });
 [TestMethod]public Task ScopeLatestSourceAndCancellationAreBounded()=>RunSta(async()=>
 {
  EnsureTestApplication();BitmapSource Make(byte value){var data=Enumerable.Repeat(value,320*200*3).ToArray();var image=BitmapSource.Create(320,200,96,96,PixelFormats.Rgb24,null,data,960);image.Freeze();return image;}
  var scope=new StudioScopeView{Source=Make(10),Mode="波形",Width=220,Height=240};var window=new Window{Width=250,Height=280,Content=scope,ShowInTaskbar=false,WindowStyle=WindowStyle.None,Opacity=0};window.Show();await scope.AnalysisWork;Assert.IsTrue(scope.PointCount>0);
  scope.Source=Make(100);scope.Source=Make(200);await scope.AnalysisWork;Assert.IsTrue(scope.PointCount>0);var screenshot=Environment.GetEnvironmentVariable("KITAO_STAGE_UI");if(screenshot is not null){Directory.CreateDirectory(screenshot);scope.UpdateLayout();await System.Windows.Threading.Dispatcher.Yield(System.Windows.Threading.DispatcherPriority.Render);Capture(scope,Path.Combine(screenshot,"scope-analysis-OFFSCREEN.png"));}var field=typeof(StudioScopeView).GetField("points",BindingFlags.Instance|BindingFlags.NonPublic)!;var values=(Point[])field.GetValue(scope)!;Assert.IsTrue(values.All(p=>Math.Abs(p.Y-(1-200d/255))<1e-5),"Only latest source may publish");
  scope.Visibility=Visibility.Collapsed;Assert.AreEqual(0,scope.PointCount);Assert.IsFalse(scope.HasPendingAnalysis);scope.Visibility=Visibility.Visible;await scope.AnalysisWork;Assert.IsTrue(scope.PointCount>0);window.Close();Assert.AreEqual(0,scope.PointCount);
 });
